"""Five composite scientific figures, with exact surrogate boundaries labeled."""
from pathlib import Path
import json
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle
from matplotlib.ticker import MaxNLocator
from vendor.pp import exact_linear as E
from turn_observability_design import row

def run(out,original,figures):
    out,original,figures=Path(out),Path(original),Path(figures);figures.mkdir(parents=True,exist_ok=True);d=pd.read_pickle(out/'private_rows.pkl');source=pd.read_pickle(out/'private_source.pkl');diag=json.loads((out/'diagnostics.json').read_text());pop=json.loads((out/'population.json').read_text());old=json.loads((original/'population.json').read_text());design=json.loads((out/'observability_design.json').read_text());example=json.loads((out/'private_paired_example.json').read_text())
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'figure.facecolor':'#f5f8fc','axes.facecolor':'#f5f8fc','axes.titleweight':'bold'})
    fig,ax=plt.subplots(1,2,figsize=(15,5.5),layout='constrained')
    for key,label,color in [('source','Combine drill','#4655ad'),('game','NFL route','#087e7b')]:
        z=example[key];q=np.array(z['q']);u=q[2]-q[0];u/=np.linalg.norm(u);q=q@np.array([[u[0],-u[1]],[u[1],u[0]]]);q[:,1]*=1 if q[-1,1]>=0 else -1;ax[0].plot(q[:,0],q[:,1],'-o',ms=4,lw=2,color=color,label=label);ax[1].plot(z['t'],np.array(z['speed'])/z['entry'],lw=3,color=color,label=label)
    ax[0].set_aspect('equal',adjustable='datalim');ax[0].set(xlabel='Along entry · yards',ylabel='Across entry · yards',title='Same development receiver · same route family');ax[0].legend();ax[1].axvspan(0,.5,color='#ddb259',alpha=.2,label='Measured deficit window');ax[1].axvline(example['release_relative_seconds'],ls=':',color='#c75a75',label='NFL pass release');ax[1].axhline(.9,color='gray',ls='--',lw=1);ax[1].set(xlabel='Seconds from anchored turn',ylabel='Speed / approach speed',title=f"Paired {example['route']} movement profiles");ax[1].legend(fontsize=9);fig.suptitle('The same receiver faces different movement demands · first qualifying heading changes',fontsize=16);fig.savefig(figures/'01_paired_turn_geometry.png',dpi=160);plt.close(fig)
    fig,ax=plt.subplots(2,3,figsize=(16,9),layout='constrained');flat=ax.ravel();total=old['all_qualifying_game_turns'];complete=total-old['incomplete_half_second_turns'];flat[0].bar(['Before release\ntruncation','Full observed\nfollow-up'],[complete,total],color=['#c85f75','#087e7b']);flat[0].set(ylabel='Turns with a measured half-second response',title='Correct timing restores 1,234 windows');flat[0].text(.5,total*.6,f'{complete:,} → {total:,}',ha='center',fontsize=17,fontweight='bold')
    for axis,route in zip(flat[1:5],['IN','OUT','SLANT','HITCH']):
        s=source[source.draft_year.isin([2023,2024])&source.route_ran.eq(route)];g=d[d.draft_year.eq(2025)&d.route_ran.eq(route)];axis.scatter(g.game_entry,np.rad2deg(g.game_angle),s=15,alpha=.25,color='#087e7b',label='NFL 2025');axis.scatter(s.entry,np.rad2deg(s.angle),s=25,alpha=.55,color='#4655ad',label='Combine earlier classes');pct=diag['source_game_demand_overlap_2025'][route]['inside_earlier_source_5_95_rectangle_fraction'];axis.set(xlabel='Approach speed · yd/s',ylabel='Turn demand · degrees',title=f'{route} · {100*pct:.1f}% inside source rectangle');axis.legend(fontsize=8)
        bounds=s[['entry','angle']].quantile([.05,.95]).to_numpy();lo,hi=bounds[0],bounds[1];axis.add_patch(Rectangle((lo[0],np.rad2deg(lo[1])),hi[0]-lo[0],np.rad2deg(hi[1]-lo[1]),fill=False,edgecolor='#cc9b32',linewidth=2,linestyle='--'))
    flat[5].axis('off');flat[5].text(0,.95,'Transfer requires comparable demands.',fontsize=14,weight='bold');flat[5].text(0,.78,'Source support uses earlier-class 5th–95th\npercentiles in speed and angle.\n\nThe rectangle is a diagnostic, not a\nvalidated biological boundary.\n\nA stop route can require strong braking;\nlower deficit is not universally better.',fontsize=12,va='top');fig.suptitle('A timed drill and an NFL route often ask different questions of the athlete',fontsize=17);fig.savefig(figures/'02_timing_and_demand_support.png',dpi=150);plt.close(fig)
    fig,ax=plt.subplots(1,3,figsize=(16,5),layout='constrained')
    for axis,target,title,units in zip(ax,['burden','separation','yac'],['Half-second movement transfer','Separation at pass release','Raw yards after catch'],['seconds²','yards²','yards²']):
        r=json.loads((out/target/'results.json').read_text())
        for i,key in enumerate(['nested','exploratory_2025']):
            z=r[key]['execution_increment'];axis.plot(z['ci95'],[i,i],lw=5,color='#087e7b');axis.scatter(z['delta_mse'],i,s=65,color='#4655ad')
        axis.axvline(0,color='gray',ls=':');axis.set_yticks([0,1],['Earlier nested','2025 exploratory']);axis.set(xlabel=f'Demand-control − execution MSE · {units}',title=title);axis.margins(y=.45)
        axis.xaxis.set_major_locator(MaxNLocator(nbins=5));axis.ticklabel_format(axis='x',style='sci',scilimits=(-3,3))
    fig.suptitle('Positive favors added Combine execution · small player samples and exploratory comparisons',fontsize=15);fig.savefig(figures/'03_transfer_uncertainty.png',dpi=160);plt.close(fig)
    fig,ax=plt.subplots(1,3,figsize=(17,5.5),layout='constrained');r=json.loads((out/'yac_reference/results.json').read_text());vals=r['exploratory_2025']['mse'];names=['provided_expected_YAC','conventional','source_demands','execution'];ax[0].barh(range(4),[vals[n] for n in names],color=['#9caebe','#9caebe','#d6ae5d','#087e7b']);ax[0].set_yticks(range(4),['Supplied expected YAC','+ Conventional correction','+ Source-demand correction','+ Execution correction']);ax[0].set(xlabel='Player-balanced MSE · yards²',title='The stronger reference limits the gain');ax[0].invert_yaxis()
    z=diag['raw_yac_identity_shuffles'];ax[1].hist(z['mse'],bins=10,color='#9caebe',edgecolor='white');ax[1].axvline(z['real_profile_mse'],color='#c75a75',lw=3,label='Actual profile');ax[1].set(xlabel='Raw-YAC test MSE · yards²',ylabel='Training profile swaps',title='Profile identity is a useful diagnostic');ax[1].legend(fontsize=9)
    values=diag['same_drill_first_last_spearman'];keys=['entry','angle','burden','retention','exit_ratio','area'];ax[2].barh(range(6),[values[k] for k in keys],color='#4655ad');ax[2].set_yticks(range(6),['Approach speed','Turn angle','Recovery deficit','Speed retention','Exit-speed ratio','Curve area']);ax[2].set(xlabel='First/last Spearman correlation',xlim=(0,1),title=f"Repeatability · {diag['same_drill_repeat_pairs']} same-drill pairs");ax[2].invert_yaxis();fig.suptitle('A nominal 16% raw-model gain is not a proven advantage over expected YAC',fontsize=16);fig.savefig(figures/'04_reference_and_repeatability.png',dpi=160);plt.close(fig)
    # Construct two bounded hypothetical surfaces invisible at actual source conditions.
    for player,g in d[d.draft_year.eq(2023)].groupby('nfl_id',sort=True):
        s=source[source.nfl_id.eq(player)];S=tuple(row(a.entry,a.angle) for a in s.itertuples());G=tuple(row(a.game_entry,a.game_angle) for a in g.itertuples());f=E.target_factor(S,G)
        if f['status']=='AMBIGUOUS' and E.rank(S)>=4:break
    coeff=np.array(f['invisible_vector'],float);ss=np.linspace(2.5,10,45);aa=np.linspace(25,150,45);X,Y=np.meshgrid(ss,aa);u=X/8;w=Y/90;basis=np.stack([np.ones_like(u),u,w,u*w,u*u,w*w],axis=-1);H=basis@coeff;eps=.08/max(np.abs(H).max(),1e-12);B0=.12+eps*H;B1=.12-eps*H;assert np.max(np.abs(np.array(S,float)@coeff))<1e-10
    fig=plt.figure(figsize=(16,6),layout='constrained');a=fig.add_subplot(121,projection='3d');b=fig.add_subplot(122);a.plot_surface(X,Y,B0,color='#087e7b',alpha=.6,linewidth=0);a.plot_surface(X,Y,B1,color='#c75a75',alpha=.6,linewidth=0);source_xy=np.array([[float(z[1])*8,float(z[2])*90] for z in S]);a.scatter(source_xy[:,0],source_xy[:,1],np.full(len(S),.12),c='#18283f',s=55,depthshade=False);a.set(xlabel='Approach speed · yd/s',ylabel='Turn angle · degrees',zlabel='Hypothetical deficit · seconds',title='Two models agree at the source conditions');a.view_init(25,-120)
    keys=sorted(map(int,design['minimum_additional_measurement_histogram']));b.bar(keys,[design['minimum_additional_measurement_histogram'][str(k)] for k in keys],color='#4655ad');b.set(xticks=keys,xlabel='Minimum extra scalar measurements',ylabel='Players',title=f"{design['ambiguous_NFL_target_maps']}/{design['players_with_source_and_game_demands']} source designs leave NFL targets ambiguous");fig.suptitle('Exact only for the supplied quadratic surrogate · not a theorem about athlete physiology',fontsize=15);fig.savefig(figures/'05_identifiability_and_measurement_design.png',dpi=160);plt.close(fig)
    return [figures/f'{i:02d}_{name}.png' for i,name in enumerate(['paired_turn_geometry','timing_and_demand_support','transfer_uncertainty','reference_and_repeatability','identifiability_and_measurement_design'],1)]
if __name__=='__main__':run(Path(__file__).parent/'private_post_release',Path(__file__).parent/'private_turn_transfer',Path(__file__).parent/'receipts/turn_transfer')
